// ====== DEMO CONFIG – move these to n8n Credentials / Variables before production ======
return [{
  json: {
    SUPABASE_URL: "https://YOUR-PROJECT.supabase.co",
    SUPABASE_SERVICE_KEY: "YOUR-SERVICE-ROLE-KEY",      // server-side only, never in the dashboard
    TEAMS_WEBHOOK: "https://YOUR-TENANT.webhook.office.com/webhookb2/....",
    DASHBOARD_URL: "https://your-dashboard-url/",      // linked at the bottom of every email/card
    EMAIL_TO: "tharakajce.97@gmail.com",                       // comma-separated list for the team digest
    EMAIL_FROM: "Threat Intel <tharakajce.97@gmail.com>",        // must match the SMTP credential account

    // Vendors/products in client environments. Case-insensitive substring match on
    // vendorProject + product (KEV) and title + summary (news).
    VENDOR_ALLOWLIST: [
      "Microsoft","Windows","Exchange","SharePoint","Office","Entra","Azure","Intune",
      "Fortinet","FortiGate","FortiOS","FortiManager","FortiAnalyzer","FortiClient",
      "ConnectWise","ScreenConnect","NinjaOne","Ninja RMM",
      "Cisco","Ivanti","Citrix","NetScaler","VMware","Broadcom","Veeam","SonicWall",
      "Palo Alto","PAN-OS","GlobalProtect","Apple","iOS","macOS","Google","Chrome","Chromium",
      "Mozilla","Firefox","Adobe","Acrobat","Atlassian","Confluence","Jira","Oracle",
      "SolarWinds","Zoho","ManageEngine","Synology","QNAP","Ubiquiti","UniFi",
      "Dell","Lenovo","Progress","MOVEit","GitLab","Jenkins","OpenSSL","Linux","Ubuntu",
      "Samba","PaperCut","Kaseya","CrowdStrike","Proofpoint","ThreatLocker","7-Zip","WinRAR",
      "Auvik","Proxmox","Hyper-V","SQL Server","Teams","OneDrive","Outlook","Defender"
    ],

    // High-signal phrases for news scoring (weight added to score)
    SIGNAL_TERMS: {
      "zero-day": 3, "0-day": 3, "actively exploited": 3, "in the wild": 3,
      "exploited": 2, "ransomware": 2, "critical": 1, "rce": 2, "remote code execution": 2,
      "authentication bypass": 2, "patch now": 2, "emergency": 2, "out-of-band": 2,
      "cve-": 1, "australia": 2, "australian": 2, "msp": 2, "mssp": 2, "rmm": 2,
      "supply chain": 1, "phishing": 1, "data breach": 1
    },
    MIN_SCORE: 3,                 // article is "relevant" at or above this
    NEWS_MAX_AGE_DAYS: 7,         // ignore feed items older than this (MSRC feed returns its whole history)
    KEV_LOOKBACK_DAYS: 14,        // on first run, only notify about KEV entries this recent
    AI_ENABLED: false,            // flip to true once ANTHROPIC key is set in the AI node

    // CVE Watch / enrichment (TI 04, TI 05)
    NVD_API_KEY: "YOUR-NVD-API-KEY",   // https://nvd.nist.gov/developers/request-an-api-key
    CVSS_MIN: 7.0,                     // CVE Watch keeps CVEs at or above this base score
    CVE_LOOKBACK_HOURS: 48,            // NVD publication window per run
    ENRICH_BATCH: 60                   // KEV rows enriched per TI 05 run
  }
}];

// One item per feed. Source label is derived from the hostname later, so this list is all you edit.
const feeds = [
  ["BleepingComputer", "https://www.bleepingcomputer.com/feed/"],
  ["The Hacker News",  "https://feeds.feedburner.com/TheHackersNews"],
  ["AskWoody",         "https://www.askwoody.com/feed/"],
  ["ASD ACSC",         "https://www.cyber.gov.au/rss/alerts"],
  ["ASD ACSC",         "https://www.cyber.gov.au/rss/advisories"],
  ["CISA",             "https://www.cisa.gov/cybersecurity-advisories/cybersecurity-advisories.xml"],
  ["MSRC",             "https://api.msrc.microsoft.com/update-guide/rss"],
  ["Fortinet PSIRT",   "https://filestore.fortinet.com/fortiguard/rss/ir.xml"],
];
return feeds.map(([source, url]) => ({ json: { source, url } }));

const cfg = $('Config').first().json;
const allow = cfg.VENDOR_ALLOWLIST.map(s => s.toLowerCase());
const signals = Object.entries(cfg.SIGNAL_TERMS);

// NOTE: the Code node sandbox has no URL class, so parse the host with a regex.
const sourceFromLink = (link) => {
  try {
    const m = String(link).match(/^https?:\/\/([^\/?#]+)/i);
    if (!m) return 'unknown';
    const h = m[1].toLowerCase().replace(/^www\./, '');
    if (h.includes('bleepingcomputer')) return 'BleepingComputer';
    if (h.includes('thehackernews')) return 'The Hacker News';
    if (h.includes('askwoody')) return 'AskWoody';
    if (h.includes('cyber.gov.au')) return 'ASD ACSC';
    if (h.includes('cisa.gov')) return 'CISA';
    if (h.includes('msrc') || h.includes('microsoft.com')) return 'MSRC';
    if (h.includes('fortiguard') || h.includes('fortinet')) return 'Fortinet PSIRT';
    return h;
  } catch { return 'unknown'; }
};

const strip = (s) => (s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const seen = new Set();
const rows = [];

for (const item of $input.all()) {
  const j = item.json || {};
  let link = j.link || j.guid || j.id;
  if (!link || seen.has(link)) continue;
  seen.add(link);
  // MSRC items sometimes carry a bare CVE id instead of a URL
  if (!/^https?:\/\//i.test(link) && /^CVE-\d{4}-\d+$/i.test(link)) link = `https://msrc.microsoft.com/update-guide/vulnerability/${link.toUpperCase()}`;
  const source = sourceFromLink(link);

  // Age filter: some feeds (MSRC) return their entire history; keep only recent items
  const publishedRaw = j.isoDate || j.pubDate || null;
  const publishedMs = publishedRaw ? Date.parse(publishedRaw) : NaN;
  if (!isNaN(publishedMs) && publishedMs < Date.now() - (cfg.NEWS_MAX_AGE_DAYS || 7) * 86400000) continue;

  const title = strip(j.title);
  const summary = strip(j.contentSnippet || j.content || j.description || j['content:encoded']).slice(0, 600);
  const hay = `${title} ${summary}`.toLowerCase();

  const matched = [];
  let score = 0;
  for (const a of allow) if (hay.includes(a)) { matched.push(a); score += 2; }
  for (const [term, w] of signals) if (hay.includes(term)) { matched.push(term); score += w; }
  // a vendor hit in the TITLE is a strong signal
  const t = title.toLowerCase();
  if (allow.some(a => t.includes(a))) score += 2;

  // Noise rule: MSRC republishes every Chromium CVE (Edge inherits them). Action is always "update Edge",
  // so keep them stored but out of the digest.
  const noise = source === 'MSRC' && /^Chromium\b/i.test(title);
  if (noise) { score = 0; matched.push('chromium-edge-batch'); }

  rows.push({
    link, title,
    source,
    published_at: !isNaN(publishedMs) ? new Date(publishedMs).toISOString() : new Date().toISOString(),
    summary,
    score,
    matched_terms: [...new Set(matched)],
    relevant: score >= cfg.MIN_SCORE,
  });
}
if (rows.length === 0) return [];
return [{ json: { rows, fetched: $input.all().length, unique: rows.length,
                  relevant: rows.filter(r => r.relevant).length } }];

// ===== OPTIONAL AI RELEVANCY CHECK (disabled) =====
// When cfg.AI_ENABLED is true, this node prepares one request per relevant article for the
// "Claude relevancy check" HTTP node. Leave disabled for keyword-only mode.
const cfg = $('Config').first().json;
if (!cfg.AI_ENABLED) return [];
const rows = $input.first().json.rows.filter(r => r.relevant);
return rows.map(r => ({ json: {
  link: r.link,
  prompt: `You triage threat intelligence for an Australian MSSP. Our stack: Microsoft 365/Defender XDR/Sentinel/Entra, Fortinet (FortiGate/FortiManager/FortiAnalyzer), ConnectWise RMM, NinjaOne RMM, CrowdStrike Falcon, Proofpoint, ThreatLocker, Nessus, Auvik, ~50 SMB client tenants. Answer in JSON only: {"relevant": true|false, "reason": "<one line>"}.\n\nTitle: ${r.title}\nSummary: ${r.summary}`
}}));
